using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Hosting;

namespace EndToEnd.Tests.Infrastructure;

/// <summary>
/// A service hosted in the test process, with its HTTP API on an in-memory TestServer.
/// TEntryPoint is any public type from the service's assembly: Program is generated by the compiler,
/// and both services have one.
/// </summary>
public sealed class ServiceFactory<TEntryPoint>(IReadOnlyDictionary<string, string?> settings)
    : WebApplicationFactory<TEntryPoint> where TEntryPoint : class
{
    protected override IHost CreateHost(IHostBuilder builder)
    {
        // Program.cs reads its connection strings before builder.Build(), while app configuration added by the factory
        // arrives only after that (dotnet/aspnetcore#37680). Host configuration is passed to the service's Main
        // as command-line arguments, so the service sees these values from its first line.
        builder.ConfigureHostConfiguration(configuration => configuration.AddInMemoryCollection(settings));
        return base.CreateHost(builder);
    }
}
